// === Tab: main.js ===
/*
Coronavirus simulation

Roughly simulates an outbreak using different social distances.
Play around with the variables at the top to explore how it can spread in different environments.

Inspired by this article:
https://www.washingtonpost.com/graphics/2020/world/corona-simulator/?fbclid=IwAR1tGUaApSRIXYCArDRx3kra6xkTNUkh4k4EWonp0d0XOvU2P9z7pVqiOcQ

Author:
  Jason Labbe

Site:
  jasonlabbe3d.com
*/

var population = 200;
var personSize = 10;
var recoveryTime = 300;
var deathChance = 7; // Out of 100%
var socialDistance = 0; // Out of 100%

var _bounds = 380;
var _people = [];

var _normalCount = 0;
var _sickCount = 0;
var _recoveryCount = 0;
var _deathCount = 0;
var _socialDistanceCount = 0;

var _normalColor;
var _sickColor;
var _recoveryColor;
var _deadColor;

const NORMAL = 0;
const SICK = 1;
const RECOVER = 2;
const DEAD = 3;

function setup() {
pixelDensity(pixelDensity());
	let side = max(windowWidth, windowHeight);
	createCanvas(_bounds, _bounds + 100, P2D);

	textStyle(BOLD);

	_normalColor = color(80, 200, 80);
	_sickColor = color(210, 200, 0);
	_recoveryColor = color(203, 138, 192);
	_deadColor = color(255, 50, 50);

  _noDistButton = createButton("0 Sosial Avstand");
  _noDistButton.position(10, _bounds - 25);
	_noDistButton.mousePressed(onNoDistTriggered);

  _lowDistButton = createButton("Hjemme Oppfordring");
  _lowDistButton.position(130, _bounds - 25);
	_lowDistButton.mousePressed(onLowDistTriggered);

  _highDistButton = createButton("Karantene");
  _highDistButton.position(280, _bounds - 25);
	_highDistButton.mousePressed(onHighDistTriggered);

	resetSim();
}

function draw() {
	noStroke();
	fill(255);
	rect(0, 0, _bounds, _bounds);

	for (let i = 0; i < _people.length; i++) {
		_people[i].move();
		_people[i].display();
	}

	displayStats();

	if (_sickCount == 0) {
		displayEnd();
	} else {
		displayGrapth();
	}
}

function resetSim() {
	frameCount = 0;
	_people = [];
	_normalCount = population;
	_sickCount = 0;
	_recoveryCount = 0;
	_deathCount = 0;
	_socialDistanceCount = 0;

	noStroke();
	fill(100);
	rect(0, _bounds, _bounds, _bounds - 100);

	for (let i = 0; i < population; i++) {
		let person = new Person(random(_bounds), random(_bounds));
		_people.push(person);

		if (i / population * 100 < socialDistance) {
			person.vel.mult(0);
			_socialDistanceCount++;
		}
	}

	let patientZero = _people[floor(random() * _people.length)];
	patientZero.setState(SICK);
	patientZero.vel = p5.Vector.random2D(); // Patient zero doesn't practice social distancing.
}

function displayStats() {
	noStroke();
	textAlign(LEFT);
	textSize(14);

	fill(255, 200);
	rect(0, 0, 200, 130);

	fill(0);
	text("Befolknings antall: " + _people.length, 10, 20);
	text("Sosial avstand: " + _socialDistanceCount + " (" + percentage(_socialDistanceCount, _people.length) + "%)", 10, 40);

	fill(_normalColor);
	text("Friske: " + _normalCount + " (" + percentage(_normalCount, _people.length) + "%)", 10, 60);

	fill(_sickColor);
	text("Syke: " + _sickCount + " (" + percentage(_sickCount, _people.length) + "%)", 10, 80);

	fill(_recoveryColor);
	text("Blitt frisk/imun: " + _recoveryCount + " (" + percentage(_recoveryCount, _people.length) + "%)", 10, 100);

	fill(_deadColor);
	text("Døde: " + _deathCount + " (" + percentage(_deathCount, _people.length) + "%)", 10, 120);
}

function displayGrapth() {
	let sickHeight = map(_sickCount, 0, _people.length, height - 100, height) - _bounds;
	let normalHeight = map(_normalCount, 0, _people.length, height - 100, height) - _bounds;
	let recoveryHeight = map(_recoveryCount, 0, _people.length, height - 100, height) - _bounds;
	let deadHeight = map(_deathCount, 0, _people.length, height - 100, height) - _bounds;

	let speed = frameCount * 0.25;
	let y = height;

	strokeWeight(1);

	stroke(_deadColor);
	line(speed, y, speed, y - deadHeight);
	y -= deadHeight;

	stroke(_sickColor);
	line(speed, y, speed, y - sickHeight);
	y -= sickHeight;

	stroke(_normalColor);
	line(speed, y, speed, y - normalHeight);
	y -= normalHeight;

	stroke(_recoveryColor);
	line(speed, y, speed, y - recoveryHeight);
	//y -= recoveryHeight;
}

function displayEnd() {
	noStroke();
	fill(0);
	textAlign(CENTER);
	textSize(50);
	text("Utbrudd Over", width / 2, height / 2);
}

function percentage(value, maxValue) {
	return (value / maxValue * 100.0).toFixed(1);
}

function onNoDistTriggered() {
	socialDistance = 0;
	resetSim();
}

function onLowDistTriggered() {
	socialDistance = 30;
	resetSim();
}

function onHighDistTriggered() {
	socialDistance = 85;
	resetSim();
}

// === Tab: person.js ===
function Person(x, y) {
	this.pos = new p5.Vector(x, y);
	this.vel = p5.Vector.random2D();
	this.state = NORMAL;
	this.infectedTime = 0;

	this.move = function() {
		if (this.state == DEAD) {
			return;
		}

		this.pos.add(this.vel);
		this.keepInBounds();

		if (this.state == SICK) {
			this.infectOthers();
			this.tryToRecover();
		}
	}

	this.infectOthers = function() {
		for (let i = 0; i < _people.length; i++) {
			let other = _people[i];
			if (this == other || other.state != NORMAL) {
				continue;
			}

			if (dist(this.pos.x, this.pos.y, other.pos.x, other.pos.y) < personSize) {
				other.setState(SICK);
				other.infectedTime = frameCount;
			}
		}
	}

	this.tryToRecover = function() {
		if (frameCount > this.infectedTime + recoveryTime) {
			if (random() < deathChance / 100.0) {
				this.setState(DEAD);
			} else {
				this.setState(RECOVER);
			}
		}
	}

	this.keepInBounds = function() {
		let halfSize = personSize / 2;

		if (this.pos.x - halfSize < 0 || this.pos.x + halfSize > _bounds) {
			this.vel.x *= -1;
			this.pos.x = constrain(this.pos.x, halfSize, _bounds - halfSize);
		}

		if (this.pos.y - halfSize < 0 || this.pos.y + halfSize > _bounds) {
			this.vel.y *= -1;
			this.pos.y = constrain(this.pos.y, halfSize, _bounds - halfSize);
		}
	}

	this.display = function() {
		strokeWeight(personSize);

		if (this.state == NORMAL) {
			stroke(_normalColor);
		} else if (this.state == SICK) {
			stroke(_sickColor);
		} else if (this.state == RECOVER) {
			stroke(_recoveryColor);
		} else if (this.state == DEAD) {
			stroke(_deadColor);
		}

		point(this.pos.x, this.pos.y);
	}

	this.setState = function(newState) {
		this.state = newState;

		if (newState == SICK) {
			_normalCount --;
			_sickCount++;
		} else if (this.state == RECOVER) {
			_sickCount--;
			_recoveryCount++;
		} else if (this.state == DEAD) {
			_sickCount--;
			_deathCount++;
		}
	}
}

